#pragma once

#include <algorithm>
#include <cstdint>
#include <random>

namespace mipx::test {

// Keep the fixtures generated by the original libstdc++ distributions.
// mt19937 specifies its raw stream, but the standard distributions can map
// that stream differently (including how many draws they consume).
inline int validityInt(std::mt19937& rng, int lo, int hi) {
    const auto width = static_cast<std::uint64_t>(static_cast<std::int64_t>(hi) - lo + 1);
    const auto threshold = (std::uint64_t{1} << 32) % width;
    std::uint64_t product;
    do {
        product = rng() * width;
    } while (static_cast<std::uint32_t>(product) < threshold);
    return static_cast<int>(lo + static_cast<std::int64_t>(product >> 32));
}

inline double validityReal(std::mt19937& rng, double lo, double hi) {
    const auto low = static_cast<std::uint64_t>(rng());
    const auto high = static_cast<std::uint64_t>(rng());
    const auto bits = (high << 32) | low;
    // Conversion can round the largest inputs up to 1. Keep the unit draw
    // half-open as in the original generator.
    const double unit = std::min(static_cast<double>(bits) * 0x1p-64, 0x1.fffffffffffffp-1);
    return lo + unit * (hi - lo);
}

}  // namespace mipx::test
